import React, { useState, useMemo, useEffect } from 'react';
import { GRADE_8_SYLLABUS } from '../data/grade8Syllabus';
import { useAuthStore } from '../store/authStore';
import { canAccessAllChapters, isFreeTrialOpenLesson } from '../utils/premiumAccess';
import '../styles/grade8-syllabus.css';
import { expandDigitsInLessonText } from '../utils/lessonNumberSpeech';
import { getTextbookMetaForLesson } from '../utils/textbookCovers';

export interface SyllabusChapter {
  id: string;
  num: string;
  chNumber: string;
  title: string;
  hindiTitle?: string;
  englishTitle: string;
  page: string;
  category: string;
  genreBadge: string;
  theme: string;
  grammarFocus: string;
  sampleVerse?: string;
  status: 'available' | 'in_curriculum' | 'overview';
  icon: string;
}

interface Grade8SyllabusModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectLesson?: (lessonId: string) => void;
  onOpenCbseGuide?: () => void;
  /** Defaults to the Class 8 index. Pass Grade 7 or Grade 9 data to reuse this modal. */
  syllabus?: readonly SyllabusChapter[];
  gradeBadge?: string;
  intro?: string;
  coreLessonCount?: number;
  appendixCount?: number;
  pageSpan?: string;
  pageStatSuffix?: string;
  searchPlaceholder?: string;
  /** Lesson ids that can be opened. Defaults to ids starting with lessonIdPrefix. */
  lessonIdPrefix?: string;
  knownLessonIds?: readonly string[];
  /** Class 8 and 9 lessons need an account. Class 7 does not. */
  accessGated?: boolean;
  accountNote?: string;
  examTitle?: string;
  examBlurb?: string;
}

const FILTER_LABELS: { id: string; label: string }[] = [
  { id: 'all', label: 'सर्वम् · All' },
  { id: 'shlokas', label: 'श्लोकाः · Shlokas' },
  { id: 'stories', label: 'कथाः · Stories' },
  { id: 'dialogue', label: 'सम्भाषणम् · Dialogues' },
  { id: 'grammar', label: 'व्याकरणम् · Grammar' },
  { id: 'preface', label: 'प्रस्तावना · Preface' },
  { id: 'anthem', label: 'राष्ट्रगीतम् · Anthem' },
];

export const Grade8SyllabusModal: React.FC<Grade8SyllabusModalProps> = ({
  isOpen,
  onClose,
  onSelectLesson,
  onOpenCbseGuide,
  syllabus,
  gradeBadge = 'अष्टमकक्षा-पाठ्यक्रमः · Deepakam 8th grade · दीपकम',
  intro = 'Complete index of all 13 textbook chapters, introductory prayers, and grammatical appendices with exact page references.',
  coreLessonCount = 13,
  appendixCount = 3,
  pageSpan = 'Page iii to 173',
  pageStatSuffix = 'References',
  searchPlaceholder = '🔍 Search chapter title, page number, grammar topic (e.g. डिजिभारतम्, Page 49, सङ्ख्याशब्दाः)...',
  lessonIdPrefix = 'grade8_',
  knownLessonIds,
  accessGated = true,
  accountNote = 'Prārthanā & Chapter 1 are open under your 14-day free trial! Register or sign in for free to unlock all subsequent chapters.',
  examTitle = 'CBSE Class 8 Sanskrit Exam Guide & Question Directives',
  examBlurb = 'Master standardized instructions (यथानिर्देशम्, अन्वयः, घटनाक्रमः), 10 interrogative क-कार words, and grammatical components (कर्तृपदम्, क्रियापदम्) for board-pattern scoring.',
}) => {
  const chapters: readonly SyllabusChapter[] = syllabus ?? GRADE_8_SYLLABUS;
  const { isAdminLoggedIn, currentUser, openAuthModal } = useAuthStore();
  const canReadAllChapters = canAccessAllChapters(currentUser, isAdminLoggedIn);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');
  const [speakingId, setSpeakingId] = useState<string | null>(null);

  // Close on Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  // Web Speech API for Sanskrit pronunciation
  const speakText = (id: string, text: string) => {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    if (speakingId === id) {
      setSpeakingId(null);
      return;
    }
    const utterance = new SpeechSynthesisUtterance(expandDigitsInLessonText(text));
    utterance.lang = 'hi-IN'; // Devanagari phonology
    utterance.rate = 0.85;
    utterance.pitch = 1.0;
    utterance.onend = () => setSpeakingId(null);
    utterance.onerror = () => setSpeakingId(null);
    setSpeakingId(id);
    window.speechSynthesis.speak(utterance);
  };

  const filteredChapters = useMemo(() => {
    return chapters.filter((ch) => {
      const matchesCategory = activeCategory === 'all' || ch.category === activeCategory;
      if (!matchesCategory) return false;

      if (!searchQuery.trim()) return true;
      const q = searchQuery.toLowerCase().trim();
      return (
        ch.title.toLowerCase().includes(q) ||
        ch.englishTitle.toLowerCase().includes(q) ||
        ch.chNumber.toLowerCase().includes(q) ||
        ch.page.toLowerCase().includes(q) ||
        ch.theme.toLowerCase().includes(q) ||
        ch.grammarFocus.toLowerCase().includes(q) ||
        (ch.sampleVerse && ch.sampleVerse.toLowerCase().includes(q))
      );
    });
  }, [searchQuery, activeCategory, chapters]);

  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = { all: chapters.length };
    chapters.forEach((ch) => {
      counts[ch.category] = (counts[ch.category] || 0) + 1;
    });
    return counts;
  }, [chapters]);

  const filterTabs = FILTER_LABELS.filter((tab) => tab.id === 'all' || (categoryCounts[tab.id] || 0) > 0);

  if (!isOpen) return null;

  return (
    <div className="g8-modal-overlay" onClick={onClose} role="dialog" aria-modal="true" aria-labelledby="g8-title">
      <div className="g8-modal" onClick={(e) => e.stopPropagation()}>
        {/* Modal Header */}
        <div className="g8-modal-header">
          <div className="g8-modal-header-with-cover">
            <div className="g8-modal-cover-thumb">
              <img
                src={
                  gradeBadge.includes('नवम') || gradeBadge.includes('9')
                    ? '/textbooks/ncert-sharada-class9.jpg'
                    : gradeBadge.includes('सप्तम') || gradeBadge.includes('7')
                    ? '/textbooks/ncert-deepakam-class7.webp'
                    : '/textbooks/ncert-deepakam-class8.jpg'
                }
                alt="NCERT Sanskrit Textbook Cover"
                className="g8-modal-cover-img"
              />
            </div>
            <div className="g8-modal-title-box">
              <span className="g8-badge-grade">{gradeBadge}</span>
              <h2 id="g8-title">
                <span>📜</span> पाठानुक्रमणिका (Table of Contents)
              </h2>
              <p>{intro}</p>
            </div>
          </div>
          <button
            type="button"
            className="g8-modal-close-btn"
            onClick={onClose}
            title="Close index (Esc)"
            aria-label="Close modal"
          >
            ✕
          </button>
        </div>

        {/* Stats Summary Row */}
        <div className="g8-stats-row">
          <div className="g8-stat-chip">
            <span>📚</span>
            <span><strong>{chapters.length}</strong> Total Modules</span>
          </div>
          <div className="g8-stat-chip">
            <span>📖</span>
            <span><strong>{coreLessonCount}</strong> Core Lessons</span>
          </div>
          <div className="g8-stat-chip">
            <span>📐</span>
            <span><strong>{appendixCount}</strong> Grammar Appendices</span>
          </div>
          <div className="g8-stat-chip">
            <span>📄</span>
            <span><strong>{pageSpan}</strong> {pageStatSuffix}</span>
          </div>
        </div>

        {/* Toolbar & Filters */}
        <div className="g8-controls-bar">
          <input
            type="text"
            className="g8-search-input"
            placeholder={searchPlaceholder}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            aria-label="Search Grade 8 Syllabus"
          />

          <div className="g8-filters">
            {filterTabs.map((tab) => (
              <button
                key={tab.id}
                type="button"
                className={`g8-filter-btn ${activeCategory === tab.id ? 'active' : ''}`}
                onClick={() => setActiveCategory(tab.id)}
              >
                {tab.label} <span className="g8-filter-count">({categoryCounts[tab.id] || 0})</span>
              </button>
            ))}
          </div>
        </div>

        {/* Modal Body / Chapter Cards */}
        <div className="g8-modal-body">
          {accessGated && !canReadAllChapters && (
            <div className="g8-upcoming-overlay-note" role="status">
              <strong>🎁 FREE TRIAL PREVIEW · निःशुल्क-परीक्षणम्</strong>
              <span>{accountNote}</span>
            </div>
          )}
          {filteredChapters.length === 0 ? (
            <div className="g8-empty-state">
              <span style={{ fontSize: '2.5rem' }}>🔍</span>
              <p style={{ fontWeight: 700, margin: '0.5rem 0 0.25rem', color: '#334155' }}>No entries found</p>
              <p style={{ color: '#64748b', fontSize: '0.9rem', margin: '0 0 1rem' }}>
                No chapter matches your query "{searchQuery}".
              </p>
              <button
                type="button"
                className="g8-filter-btn active"
                onClick={() => {
                  setSearchQuery('');
                  setActiveCategory('all');
                }}
              >
                Reset Search Filters
              </button>
            </div>
          ) : (
            filteredChapters.map((ch) => {
              const inThisReader =
                !knownLessonIds || knownLessonIds.includes(ch.id);
              const markedOpen = ch.status === 'available' || ch.id.startsWith(lessonIdPrefix);
              const isTrialOpen = isFreeTrialOpenLesson(ch.id);
              const isAvailable = inThisReader && markedOpen && (!accessGated || canReadAllChapters || isTrialOpen);
              const isSpeaking = speakingId === ch.id;
              const isVerseSpeaking = speakingId === `${ch.id}_verse`;

              return (
                <div
                  key={ch.id}
                  className={`g8-chapter-card ${isAvailable ? 'highlight' : ''}`}
                >
                  <div className="g8-card-top-row">
                    <div className="g8-card-badges">
                      <img
                        src={getTextbookMetaForLesson(ch.id).coverUrl}
                        alt="NCERT Textbook"
                        className="g8-ch-card-avatar"
                        title={getTextbookMetaForLesson(ch.id).bookTitleSa}
                      />
                      <span className="g8-ch-num-badge">
                        {ch.icon} {ch.chNumber}
                      </span>
                      <span className="g8-ch-page-badge">
                        📄 {ch.page}
                      </span>
                      <span className="g8-ch-genre-badge">{ch.genreBadge}</span>
                    </div>

                    <div className="g8-card-status">
                      {isAvailable ? (
                        <span className={`g8-status-pill ${isTrialOpen && !canReadAllChapters ? 'ready' : 'ready'}`}>
                          {isTrialOpen && !canReadAllChapters ? '🎁 Free Trial Open' : '✅ Available in App'}
                        </span>
                      ) : (
                        <span className="g8-status-pill syllabus">
                          {!canReadAllChapters ? '🔒 Requires Free Account' : '📚 In Syllabus'}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="g8-card-title-row">
                    <h3 className="g8-card-title-sa">{ch.title}</h3>
                    <button
                      type="button"
                      className="g8-audio-icon-btn"
                      onClick={() => speakText(ch.id, ch.title)}
                      title={isSpeaking ? 'Stop pronunciation' : 'Listen to Sanskrit pronunciation'}
                      aria-label={`Pronounce ${ch.title}`}
                    >
                      {isSpeaking ? '⏹️ Playing' : '🔊 Pronounce'}
                    </button>
                  </div>
                  {ch.hindiTitle && <div className="g8-card-title-hi" style={{ fontSize: '0.95rem', fontWeight: 600, color: '#b45309', marginBottom: '0.2rem' }}>🇮🇳 {ch.hindiTitle}</div>}
                  <div className="g8-card-title-en">{ch.englishTitle}</div>

                  <div className="g8-card-theme">{ch.theme}</div>

                  {ch.sampleVerse && (
                    <div className="g8-card-verse-box">
                      <div className="g8-verse-inner-header">
                        <span className="g8-verse-heading">✨ श्लोक-पंक्तिः / Sample Verse</span>
                        <button
                          type="button"
                          className="g8-verse-audio-btn"
                          onClick={() => speakText(`${ch.id}_verse`, ch.sampleVerse!)}
                          title="Listen to sample verse"
                        >
                          {isVerseSpeaking ? '⏹️ Stop' : '🔊 Chanting Audio'}
                        </button>
                      </div>
                      <div className="g8-verse-text">{ch.sampleVerse}</div>
                    </div>
                  )}

                  <div className="g8-card-grammar-box">
                    <strong>📌 व्याकरण-केन्द्रम् (Grammar Focus):</strong> {ch.grammarFocus}
                  </div>

                  <div className="g8-card-action-row">
                    {isAvailable ? (
                      <button
                        type="button"
                        className="g8-action-btn-primary"
                        onClick={() => {
                          onClose();
                          if (onSelectLesson) {
                            onSelectLesson(ch.id);
                          }
                        }}
                      >
                        📖 Open Interactive Lesson ➔
                      </button>
                    ) : !canReadAllChapters ? (
                      <button
                        type="button"
                        className="g8-action-btn-secondary"
                        onClick={() => {
                          onClose();
                          openAuthModal('register');
                        }}
                        style={{ fontSize: '0.84rem', padding: '0.45rem 0.9rem', cursor: 'pointer' }}
                      >
                        🔒 Create Free Account to Read ➔
                      </button>
                    ) : (
                      <span className="g8-card-ref-label">
                        NCERT Prescribed Text · {ch.page}
                      </span>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {onOpenCbseGuide && (
          <div
            className="g8-syllabus-guide-banner"
            onClick={() => {
              onClose();
              onOpenCbseGuide();
            }}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                onClose();
                onOpenCbseGuide();
              }
            }}
          >
            <div className="g8-guide-content">
              <span className="g8-banner-badge">📋 CBSE &amp; NCERT EXAM BLUEPRINT</span>
              <h4>{examTitle}</h4>
              <p>{examBlurb}</p>
            </div>
            <button
              type="button"
              className="g8-action-btn-primary"
              style={{ whiteSpace: 'nowrap', flexShrink: 0 }}
            >
              Open Exam Guide ➔
            </button>
          </div>
        )}

        {/* Modal Footer */}
        <div className="g8-modal-footer">
          <span className="g8-modal-footer-note">
            💡 Tap 🔊 to listen to authentic Sanskrit pronunciation for every chapter title and verse.
          </span>
          <button type="button" className="g8-filter-btn active" onClick={onClose}>
            Close Index
          </button>
        </div>
      </div>
    </div>
  );
};

export default Grade8SyllabusModal;
